  "schema_version": 1,
  "verdict": "cleared",
  "finding_class": "none",
  "rationale": "The national split is not materially overstated. Berbagi is the ordinary Indonesian form, while Malaysian PRPM records berkongsi as the standard Malay form for sharing or using something together. The forms are distinct, although their meanings overlap as direct equivalents. The English cue is acceptable, both answers fit the intended sense, the relation is correctly different-common-word, and no false-friend contrast is required.",
  "claim_reviews": [
    {
      "subject": "Indonesian answer: berbagi",
      "conclusion": "Supported as the ordinary Indonesian equivalent for sharing or giving part of something to others.",
      "material_risk": false,
      "evidence_refs": [
        "https://kbbi.kemdikbud.go.id/entri/berbagi"
      ],
      "evidence_limitation": "The official KBBI entry was not retrievable during review; confirmation relies on the established Indonesian lexical usage of berbagi."
    },
    {
      "subject": "Malaysian answer: berkongsi",
      "conclusion": "Supported as standard Malaysian Malay; PRPM defines berkongsi as acting jointly, sharing use, or sharing something with others.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=berkongsi"
      ]
    },
    {
      "subject": "National split and overlap",
      "conclusion": "The forms are not the same, and PRPM reports berbagi as absent from its current dictionary while recording berkongsi. The semantic equivalence does not materially invalidate the national distinction.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=berkongsi",
        "https://prpm.dbp.gov.my/Cari1?d=123312&keyword=berbagi"
      ],
      "evidence_limitation": "Dictionary evidence establishes standard lexical status, not comparative everyday frequency across all Malaysian and Indonesian speech communities."
    },
    {
      "subject": "English cue and sense",
      "conclusion": "To share something with others is an acceptable cue for giving some of what one has or making information, knowledge, or resources available to others. It is narrower than every sense of share but correctly matches this card.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.oxfordlearnersdictionaries.com/definition/english/share_1"
      ]
    },
    {
      "subject": "Relation and false-friend contrast",
      "conclusion": "Different-common-word is correct. Berbagi and berkongsi are direct cross-variety equivalents rather than false friends, so an empty contrast field is appropriate.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=berkongsi",
        "https://prpm.dbp.gov.my/Cari1?d=123312&keyword=berbagi"
      ]
    }
  ]
}
